import Link from "next/link";
import { Clock, FileText, Users } from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import type { ActiveExam } from "@/lib/types/exam";

type MockExam = {
  id: string;
  title: string;
  category: "Preliminary" | "Written" | "Full Syllabus";
  questions: number;
  durationMinutes: number;
  attempts: number;
  userBestScore: number | null;
  price: number;
};

const mockExams: MockExam[] = [
  {
    id: "prelim-01",
    title: "Preliminary Mock 01 — Criminal Law",
    category: "Preliminary",
    questions: 100,
    durationMinutes: 180,
    attempts: 2341,
    userBestScore: 78,
    price: 0,
  },
  {
    id: "prelim-02",
    title: "Preliminary Mock 02 — Civil Law",
    category: "Preliminary",
    questions: 100,
    durationMinutes: 180,
    attempts: 1892,
    userBestScore: null,
    price: 500,
  },
  {
    id: "prelim-03",
    title: "Preliminary Mock 03 — Full Syllabus",
    category: "Full Syllabus",
    questions: 100,
    durationMinutes: 180,
    attempts: 1502,
    userBestScore: 65,
    price: 500,
  },
  {
    id: "written-01",
    title: "Written Test — CPC Paper",
    category: "Written",
    questions: 8,
    durationMinutes: 180,
    attempts: 412,
    userBestScore: null,
    price: 800,
  },
  {
    id: "written-02",
    title: "Written Test — CrPC Paper",
    category: "Written",
    questions: 8,
    durationMinutes: 180,
    attempts: 356,
    userBestScore: null,
    price: 800,
  },
  {
    id: "written-03",
    title: "Written Test — Evidence Paper",
    category: "Written",
    questions: 8,
    durationMinutes: 180,
    attempts: 298,
    userBestScore: null,
    price: 800,
  },
];

export function MockExamsGrid({
  activeExam,
}: {
  activeExam?: ActiveExam;
}) {
  return (
    <section className="mt-8 grid gap-5 lg:grid-cols-2 xl:grid-cols-3">
      {mockExams.map((exam) => {
        const examPath =
          exam.category === "Written"
            ? `/dashboard/mock-exams/written/${exam.id}`
            : `/dashboard/mock-exams/${exam.id}`;
        const isBlocked =
          activeExam !== null &&
          activeExam !== undefined &&
          exam.id !== activeExam.examId.toString();

        return (
          <Card
            key={exam.id}
            className="flex flex-col border-border bg-card p-6 shadow-sm transition-shadow hover:shadow-md"
          >
            <div className="flex items-center justify-between">
              <Badge className={categoryClass(exam.category)}>{exam.category}</Badge>
              {exam.price === 0 ? (
                <Badge className="border-transparent bg-emerald-100 text-xs text-emerald-700">
                  Included
                </Badge>
              ) : (
                <span className="font-heading text-sm font-bold text-primary">
                  BDT {exam.price}
                </span>
              )}
            </div>
            <h2 className="mt-4 font-heading text-lg font-semibold text-primary">
              {exam.title}
            </h2>
            <div className="mt-4 flex flex-wrap gap-x-4 gap-y-2 text-xs text-muted">
              <span className="flex items-center gap-1">
                <FileText size={14} />
                {exam.questions} questions
              </span>
              <span className="flex items-center gap-1">
                <Clock size={14} />
                {exam.durationMinutes} min
              </span>
              <span className="flex items-center gap-1">
                <Users size={14} />
                {exam.attempts.toLocaleString()} attempts
              </span>
            </div>
            <div className="mt-4">
              {exam.userBestScore !== null ? (
                <>
                  <p className="text-xs text-muted">Your best score</p>
                  <p className="mt-1 font-heading text-2xl font-bold text-primary">
                    {exam.userBestScore}%
                  </p>
                </>
              ) : (
                <p className="text-xs text-muted">Not attempted yet</p>
              )}
            </div>
            <div className="mt-6 flex items-center justify-between">
              <Link
                href={examPath}
                className={
                  isBlocked
                    ? "pointer-events-none inline-flex h-11 cursor-not-allowed items-center rounded-md border border-border bg-muted/10 px-4 text-sm text-muted sm:h-9"
                    : "inline-flex h-11 items-center rounded-md bg-primary px-4 text-sm text-cream hover:bg-primary-dark sm:h-9"
                }
                aria-disabled={isBlocked}
                title={
                  isBlocked ? "Finish your active exam first." : "Start test"
                }
              >
                {isBlocked ? "Start Test" : "Start Test"}
              </Link>
              <Link
                href={`${examPath}?view=details`}
                className="text-sm text-muted hover:text-foreground"
              >
                View details →
              </Link>
            </div>
          </Card>
        );
      })}
    </section>
  );
}

function categoryClass(category: MockExam["category"]) {
  if (category === "Preliminary") return "border-primary text-primary";
  if (category === "Written") return "border-accent text-accent";
  return "border-emerald-300 text-emerald-700";
}
